UPDATE user_star_wallets
SET balance = balance + #{amount}, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}

UPDATE user_star_wallets
SET free_trip_quota_used = free_trip_quota_used + 1, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId} AND free_trip_quota_used < #{quota}

