SELECT  FROM star_transactions
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT user_id
FROM user_star_wallets
WHERE balance > 0

    AND user_id > #{afterUserId,javaType=java.util.UUID,jdbcType=OTHER}

ORDER BY user_id
LIMIT #{limit}
